function solve(n) {
  const digitSquareSum = (x) => {
    let total = 0;
    while (x > 0) {
      const d = x % 10;
      total += d * d;
      x = Math.floor(x / 10);
    }
    return total;
  };

  const seen = [];
  let cur = n;
  while (cur !== 1) {
    for (let i = 0; i < seen.length; i++) {
      if (seen[i] === cur) return false;
    }
    seen.push(cur);
    cur = digitSquareSum(cur);
  }
  return true;
}

function solve(n) {
  const digitSquareSum = (x) => {
    let total = 0;
    while (x > 0) {
      const d = x % 10;
      total += d * d;
      x = Math.floor(x / 10);
    }
    return total;
  };

  let slow = n;
  let fast = n;
  while (true) {
    slow = digitSquareSum(slow);
    fast = digitSquareSum(digitSquareSum(fast));
    if (fast === 1) return true;
    if (slow === fast) return false;
  }
}
